<?php require '../config/config.php'; require_admin(); if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM news WHERE id=?')->execute([(int)$_GET['delete']]);header('Location: news.php');exit;} if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare('INSERT INTO news(title,excerpt,image,published_at) VALUES(?,?,?,?)')->execute([$_POST['title'],$_POST['excerpt'],$_POST['image']?:'news-community.svg',$_POST['published_at']]);flash('success','News item added.');header('Location: news.php');exit;} $rows=$pdo->query('SELECT * FROM news ORDER BY published_at DESC')->fetchAll(); $title='Manage News'; require '../includes/header.php'; ?><div class="adminnav"><div class="container"><a href="index.php">Dashboard</a><a href="members.php">Members</a><a href="online-users.php">Online Users</a><a href="administrators.php">Administrators</a><a href="reports.php">Reports</a><a href="support.php">Support Requests</a><a href="donations.php">Donations</a><a href="events.php">Events</a><a href="news.php">News</a><a href="messages.php">Messages</a></div></div><section class="section"><div class="container"><h1>Manage News</h1><div class="formwrap" style="margin:20px 0"><form method="post"><div class="field"><label>Title</label><input name="title" required></div><div class="field"><label>Excerpt</label><textarea name="excerpt"></textarea></div><div class="formgrid"><div class="field"><label>Image filename</label><input name="image" value="news-community.svg"></div><div class="field"><label>Published date</label><input type="date" name="published_at" required></div></div><button class="btn">Add News</button></form></div><table class="table"><tr><th>Title</th><th>Date</th><th></th></tr><?php foreach($rows as $r): ?><tr><td><?=e($r['title'])?></td><td><?=e($r['published_at'])?></td><td><a class="date" data-confirm="Delete this news item?" href="?delete=<?=$r['id']?>">Delete</a></td></tr><?php endforeach; ?></table></div></section><?php require '../includes/footer.php'; ?>
